/// Union the incoming `versions` map onto the existing one. Incoming
/// entries win on key collision, except for versions that are already
/// locally hosted (`hosted_versions`): those are immutable and rebuilt
/// by [`preserve_hosted_version`] so a publish can never rewrite the
/// metadata of an already-published version.
fn merge_versions(
    existing: Option<&Value>,
    incoming: &Value,
    hosted_versions: Option<&Map<String, Value>>,
) -> Value {
    let mut merged = match existing {
        Some(Value::Object(obj)) => obj.clone(),
        _ => Map::new(),
    };
    if let Some(incoming_obj) = incoming.as_object() {
        for (version, incoming_entry) in incoming_obj {
            match hosted_versions.and_then(|hosted| hosted.get(version)) {
                Some(hosted_entry) => {
                    merged.insert(
                        version.clone(),
                        preserve_hosted_version(hosted_entry, incoming_entry),
                    );
                }
                None => {
                    merged.insert(version.clone(), incoming_entry.clone());
                }
            }
        }
    }
    Value::Object(merged)
}

