    let (result, dest, _tmp) = run_stream(&bytes, Some(&dist), Some(bytes.len() as u64));
    let written = result.unwrap();
    assert_eq!(written, bytes.len() as u64);
    assert_eq!(std::fs::read(&dest).unwrap(), bytes);
}

