#[test]
fn scratch_hosted_version_is_immutable_except_deprecated() {
    let now = "2025-01-02T03:04:05.678Z";
    let hosted = json!({
        "name": "foo",
        "versions": {
            "1.0.0": {
                "version": "1.0.0",
                "dependencies": { "left-pad": "^1.0.0" },
                "dist": { "integrity": "sha512-GOOD" },
                "deprecated": "old message"
            }
        }
    });
    // incoming tries to rewrite integrity + deps and set deprecated.
    let incoming = json!({
        "name": "foo",
        "versions": {
            "1.0.0": {
                "version": "1.0.0",
                "dependencies": { "left-pad": "^99.0.0" },
                "dist": { "integrity": "sha512-EVIL" },
                "deprecated": "new message"
            }
        }
    });
    let merged = merge_manifest(Some(&hosted), &incoming, Some(&hosted), now);
    let v = &merged["versions"]["1.0.0"];
    assert_eq!(v["dist"]["integrity"], "sha512-GOOD", "integrity is immutable");
    assert_eq!(v["dependencies"]["left-pad"], "^1.0.0", "deps are immutable");
    assert_eq!(v["deprecated"], "new message", "deprecated is the one mutable field");
}

#[test]
fn scratch_deprecated_cleared_when_incoming_omits_it() {
    let now = "now";
    let hosted = json!({
        "name": "foo",
        "versions": { "1.0.0": { "version": "1.0.0", "deprecated": "old", "dist": { "integrity": "sha512-X" } } }
    });
    let incoming = json!({
        "name": "foo",
        "versions": { "1.0.0": { "version": "1.0.0", "dist": { "integrity": "sha512-X" } } }
    });
    let merged = merge_manifest(Some(&hosted), &incoming, Some(&hosted), now);
    assert!(merged["versions"]["1.0.0"].get("deprecated").is_none(), "deprecated removed");
    assert_eq!(merged["versions"]["1.0.0"]["dist"]["integrity"], "sha512-X");
}

